import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ScrollbarWithAnnotationsComponent} from "./scrollbarWithAnnotations.component";
import {
  SCROLLBAR_WITH_ANNOTATIONS_ACTION,
  SCROLLBAR_WITH_ANNOTATIONS_CARD,
} from "./scrollbarWithAnnotations.types";

export * from "./scrollbarWithAnnotations.types";

registerCardComponent({
  name: SCROLLBAR_WITH_ANNOTATIONS_CARD,
  component: ScrollbarWithAnnotationsComponent,
  events: actionTypesToEvents(SCROLLBAR_WITH_ANNOTATIONS_ACTION),
});

import React, {useRef, useEffect, useCallback} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";

import type {
  ScrollbarWithAnnotationsProps,
  ScrollbarWithAnnotationsEvents,
  ScrollbarAnnotation,
} from "./scrollbarWithAnnotations.types";

import "./scrollbarWithAnnotations.css";

/**
 * ScrollbarWithAnnotations component.
 *
 * Renders a scrollable area (content comes from a Pihanga card reference) with
 * a minimap-style overlay on the scrollbar track showing coloured markers for
 * each annotation.  Clicking a marker scrolls to its position **and** emits
 * `onAnnotationClicked` so parent code can react (e.g. open a dialog/panel).
 *
 * Three marker shapes are supported (see `MarkerType` in the types file):
 *  - `"point"` – small circular dot (default)
 *  - `"bar"`   – short rectangle with fixed CSS height
 *  - `"range"` – rectangle proportional to `extent`, CSS `min-height` ensures
 *                 it stays clickable even for very small extents
 *
 * All visual properties (size, colour, opacity, transitions) are controlled
 * entirely by CSS classes so they can be overridden without touching JS.
 *
 * See `scrollbarWithAnnotations.example.ts` for wiring with a Pihanga Dialog.
 */
export const ScrollbarWithAnnotationsComponent = (
  props: PiCardProps<
    ScrollbarWithAnnotationsProps,
    ScrollbarWithAnnotationsEvents
  >,
): React.ReactNode => {
  const {
    contentCard,
    annotations = [],
    className,
    reportEventsOnScroll = false,
    cardName,
    onAnnotationClicked,
    onAnnotationHovered,
  } = props;

  const contentRef = useRef<HTMLDivElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);

  /**
   * True while the user is actively scrolling the content container.
   * Hover events are suppressed during this period to avoid a flood of
   * `onAnnotationHovered` dispatches as the overlay passes under the cursor.
   */
  const isScrollingRef = useRef(false);
  const scrollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /**
   * (Re-)renders all annotation markers inside the overlay div.
   * Called whenever annotations change or the window is resized.
   */
  const renderMarkers = useCallback(() => {
    const overlay = overlayRef.current;
    const content = contentRef.current;
    if (!overlay || !content) return;

    overlay.innerHTML = "";
    const overlayH = overlay.clientHeight;
    const contentScrollH = content.scrollHeight || 1;

    annotations.forEach((anno: ScrollbarAnnotation) => {
      const markerType = anno.markerType ?? "point";
      const topPx = (anno.position / contentScrollH) * overlayH;

      const el = document.createElement("div");
      // Shape class + type class carry all visual styling – no inline colour.
      // anno.className allows per-annotation overrides (e.g. "swa-selected").
      el.className = [
        "swa-marker",
        `swa-marker-${markerType}`,
        `swa-type-${anno.type}`,
        anno.className,
      ]
        .filter(Boolean)
        .join(" ");
      el.style.top = `${topPx}px`;

      // For range markers, set a proportional height via inline style so the
      // overlay scales with scroll content.  CSS `min-height` (defined on
      // .swa-marker-range) guarantees a minimum regardless of the ratio.
      if (markerType === "range" && anno.extent !== undefined) {
        const heightPx = (anno.extent / contentScrollH) * overlayH;
        el.style.height = `${heightPx}px`;
      }

      el.onmouseenter = () => {
        if (isScrollingRef.current) return;
        el.classList.add("swa-marker--hover");
        onAnnotationHovered?.({annotationId: anno.id, annotation: anno});
      };
      el.onmouseleave = () => {
        if (isScrollingRef.current) return;
        el.classList.remove("swa-marker--hover");
        onAnnotationHovered?.({annotationId: null, annotation: null});
      };
      el.onclick = (e) => {
        e.stopPropagation();
        if (content) {
          content.scrollTop = anno.position - 50;
        }
        onAnnotationClicked({annotationId: anno.id, annotation: anno});
      };

      overlay.appendChild(el);
    });
  }, [annotations, onAnnotationClicked, onAnnotationHovered]);

  // Re-render markers whenever annotations change, or the overlay is resized.
  // ResizeObserver fires on initial layout (when clientHeight goes from 0 to
  // the real value) as well as on subsequent window/container resizes, so
  // markers are always positioned against the actual DOM height.
  useEffect(() => {
    const overlay = overlayRef.current;
    const content = contentRef.current;

    // Observe the overlay element so markers are re-drawn whenever its size
    // changes — including the very first layout pass.
    const ro = new ResizeObserver(() => renderMarkers());
    if (overlay) ro.observe(overlay);

    const handleScroll = () => {
      // When reporting on scroll is enabled, skip suppression entirely.
      if (reportEventsOnScroll) return;

      // Set the scrolling flag so marker hover events are suppressed.
      // We intentionally do NOT dispatch a hover-clear here — marker
      // onMouseLeave events handle that when the pointer actually leaves,
      // and dispatching during scroll can interfere with parent state.
      isScrollingRef.current = true;

      // Reset the idle timer on every scroll event.
      if (scrollTimerRef.current !== null) {
        clearTimeout(scrollTimerRef.current);
      }
      scrollTimerRef.current = setTimeout(() => {
        isScrollingRef.current = false;
        scrollTimerRef.current = null;
      }, 150);
    };

    content?.addEventListener("scroll", handleScroll, {passive: true});

    return () => {
      ro.disconnect();
      content?.removeEventListener("scroll", handleScroll);
      if (scrollTimerRef.current !== null) {
        clearTimeout(scrollTimerRef.current);
      }
    };
  }, [renderMarkers, reportEventsOnScroll]);

  return (
    <div
      data-pihanga={cardName}
      className={`swa-root${className ? ` ${className}` : ""}`}
    >
      <div className="swa-content-wrapper">
        {/* Scrollable content area */}
        <div ref={contentRef} className="swa-scroll-container">
          <Card cardName={contentCard} parentCard={cardName} />
        </div>

        {/* Annotation minimap overlay – sits on top of the scrollbar track */}
        <div ref={overlayRef} className="swa-overlay" />
      </div>
    </div>
  );
};

/* ============================================================
   ScrollbarWithAnnotations – component styles
   ============================================================
   All visual knobs are expressed as CSS custom properties on :root
   so they can be overridden per-page or per-theme without touching
   any JavaScript.
   ============================================================ */

/* ── Layout ─────────────────────────────────────────────────────────────── */

/* Root container – no built-in height; size it from outside via className
   (e.g. className="h-96 h-full") or a parent flex/grid layout. */
.swa-root {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* Inner wrapper holds the scroll container + the overlay in the same
   stacking context so the overlay can be positioned absolutely over the
   scrollbar track. */
.swa-content-wrapper {
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* ── Scrollable content area ────────────────────────────────────────────── */

.swa-scroll-container {
  flex: 1;
  overflow: auto;
  min-height: 0;
}

/* Style the native scrollbar so markers are clearly visible on top of it. */
.swa-scroll-container::-webkit-scrollbar {
  width: 14px;
}

.swa-scroll-container::-webkit-scrollbar-track {
  background: var(--muted);
}

.swa-scroll-container::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: var(--radius-sm);
  border: 2px solid var(--background);
}

/* ── Overlay track ──────────────────────────────────────────────────────── */

/* Positioned over the scrollbar track; pointer-events are disabled on the
   container itself so only individual markers are interactive. */
.swa-overlay {
  position: absolute;
  right: 2px;
  top: 0;
  width: 12px;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

/* ── Shared marker base ──────────────────────────────────────────────────── */

.swa-marker {
  position: absolute;
  left: 0;
  cursor: pointer;
  pointer-events: auto;
  transition:
    opacity 0.15s ease,
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

/* ── Point marker ────────────────────────────────────────────────────────── */
/*
 * A circular dot centred on the annotation position.
 * Override --swa-point-size to change the diameter.
 */
:root {
  --swa-point-size: 10px;
}

.swa-marker-point {
  width: var(--swa-point-size);
  height: var(--swa-point-size);
  border-radius: 50%;
  border: 2px solid var(--background);
  left: 2px;
  transform: translateY(-50%);
  box-shadow: 0 0 4px color-mix(in srgb, var(--foreground) 30%, transparent);
}

.swa-marker-point.swa-marker--hover {
  transform: translateY(-50%) scale(1.5);
}

/* ── Bar marker ──────────────────────────────────────────────────────────── */
/*
 * A short rectangle with an absolute fixed height, useful for discrete events
 * that have a position but no meaningful extent.
 * Override --swa-bar-width / --swa-bar-height to resize.
 */
:root {
  --swa-bar-width: 10px;
  --swa-bar-height: 10px;
}

.swa-marker-bar {
  width: var(--swa-bar-width);
  height: var(--swa-bar-height);
  border-radius: 1px;
  opacity: 0.8;
  transform: translateY(-50%);
}

.swa-marker-bar.swa-marker--hover {
  opacity: 1;
  box-shadow: 0 0 4px color-mix(in srgb, var(--foreground) 40%, transparent);
}

/* ── Range marker ────────────────────────────────────────────────────────── */
/*
 * A rectangle whose height is set proportionally by JS (based on the
 * annotation's `extent` relative to the scroll height).
 *
 * --swa-range-min-height ensures the marker remains visible and clickable
 * even when the proportional height would be smaller than this value.
 * Override --swa-range-width / --swa-range-min-height to customise.
 */
:root {
  --swa-range-width: 8px;
  --swa-range-min-height: 8px;
}

.swa-marker-range {
  width: var(--swa-range-width);
  /* JS sets height proportionally; this guarantees a minimum regardless of ratio. */
  min-height: var(--swa-range-min-height);
  opacity: 0.4;
  border-left: 2px solid var(--background);
  border-radius: 2px;
  box-shadow: inset 0 0 2px color-mix(in srgb, var(--foreground) 20%, transparent);
}

.swa-marker-range.swa-marker--hover {
  opacity: 0.65;
  box-shadow: 0 0 6px color-mix(in srgb, var(--foreground) 40%, transparent);
}

/* ── Per-type colours ────────────────────────────────────────────────────── */
/*
 * Background colour for each annotation type.
 * Override the CSS variables below to retheme all markers for a given type
 * without touching any JavaScript.
 * --swa-color-error defaults to the theme's --destructive token; the rest
 * are bespoke colours with no direct shadcn/ui equivalent.
 */
:root {
  --swa-color-error: var(--destructive);
  --swa-color-warning: oklch(0.75 0.15 70);
  /* amber */
  --swa-color-todo: oklch(0.55 0.15 250);
  /* blue */
  --swa-color-comment: oklch(0.65 0.04 220);
  /* slate */
  --swa-color-review: oklch(0.60 0.04 100);
  /* olive-gray */
  --swa-color-fixme: oklch(0.60 0.12 55);
  /* orange-brown */
}

.swa-type-error {
  background: var(--swa-color-error);
}

.swa-type-warning {
  background: var(--swa-color-warning);
}

.swa-type-todo {
  background: var(--swa-color-todo);
}

.swa-type-comment {
  background: var(--swa-color-comment);
}

.swa-type-review {
  background: var(--swa-color-review);
}

.swa-type-fixme {
  background: var(--swa-color-fixme);
}

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const SCROLLBAR_WITH_ANNOTATIONS_CARD = "pi/scrollbar-with-annotations";

export const ScrollbarWithAnnotations = createCardDeclaration<
  ScrollbarWithAnnotationsProps,
  ScrollbarWithAnnotationsEvents
>(SCROLLBAR_WITH_ANNOTATIONS_CARD);

export const SCROLLBAR_WITH_ANNOTATIONS_ACTION = registerActions(
  SCROLLBAR_WITH_ANNOTATIONS_CARD,
  ["annotation_clicked", "annotation_hovered"],
);

export const onScrollbarAnnotationClicked =
  createOnAction<AnnotationClickedEvent>(
    SCROLLBAR_WITH_ANNOTATIONS_ACTION.ANNOTATION_CLICKED,
  );

export const onScrollbarAnnotationHovered =
  createOnAction<AnnotationHoveredEvent>(
    SCROLLBAR_WITH_ANNOTATIONS_ACTION.ANNOTATION_HOVERED,
  );

/**
 * The visual category of an annotation, which determines its colour on the
 * scrollbar minimap.
 */
export type AnnotationType =
  | "error"
  | "warning"
  | "todo"
  | "comment"
  | "review"
  | "fixme";

/**
 * Shape of the marker drawn on the scrollbar track.
 *
 * - `"point"` – a small circular dot (default).
 * - `"bar"`   – a short vertical rectangle with a fixed CSS height; useful for
 *               discrete events that have a known position but no meaningful
 *               extent.
 * - `"range"` – a vertical rectangle whose height is proportional to `extent`
 *               in the content's scroll space, with a CSS-enforced minimum
 *               height so tiny ranges remain clickable.  Requires `extent`.
 */
export type MarkerType = "point" | "bar" | "range";

/**
 * A single annotation marker placed on the scrollbar minimap.
 *
 * All positions are **pixel offsets from the top of the scrollable content**
 * (i.e. relative to `scrollHeight`).
 *
 * | markerType | required fields          |
 * |------------|--------------------------|
 * | `"point"`  | `position`               |
 * | `"bar"`    | `position`               |
 * | `"range"`  | `position` + `extent`    |
 */
export type ScrollbarAnnotation = {
  /** Unique identifier for this annotation. */
  id: string;

  /**
   * Pixel offset from the top of the scrollable content.
   * Acts as the start position for range markers.
   */
  position: number;

  /**
   * Length of the annotation in content pixels.
   *
   * Required when `markerType === "range"`.  The marker will span
   * `[position, position + extent]` in content space.
   */
  extent?: number;

  /**
   * Shape of the minimap marker.  Defaults to `"point"`.
   */
  markerType?: MarkerType;

  /** Visual category – controls colour. */
  type: AnnotationType;

  /** Short human-readable label shown in detail views. */
  title: string;

  /** Full description shown when the annotation is selected/inspected. */
  description: string;

  /**
   * Optional extra CSS class(es) applied to this marker's DOM element.
   *
   * Use this to style individual annotations differently from the default
   * type-based colour, e.g. to highlight a "selected" annotation:
   *
   *   className: "swa-selected"
   */
  className?: string;
};

export type ScrollbarWithAnnotationsProps = {
  /**
   * Pihanga card reference for the scrollable main content.
   *
   * The card is rendered inside the scroll container, so it can be any
   * Pihanga card (plain text, a Plate editor, a list, etc.).
   */
  contentCard: PiCardRef;

  /**
   * Annotations to display as coloured markers on the scrollbar track.
   */
  annotations: ScrollbarAnnotation[];

  /** Optional additional CSS class applied to the root element. */
  className?: string;

  /**
   * When `true`, `onAnnotationHovered` events are emitted even while the
   * content container is being scrolled.
   *
   * Defaults to `false` (suppression is the default) to avoid flooding Redux
   * with hover actions as markers pass under the cursor during scroll.
   */
  reportEventsOnScroll?: boolean;
};

/** Emitted when the user clicks an annotation marker. */
export type AnnotationClickedEvent = {
  /** ID of the clicked annotation. */
  annotationId: string;
  /** Full annotation object for convenience. */
  annotation: ScrollbarAnnotation;
};

/**
 * Emitted when the user hovers over (or away from) an annotation marker.
 *
 * `annotationId` / `annotation` are `null` when the pointer leaves a marker.
 *
 * ⚠️  This event fires frequently during normal cursor movement.  Handlers
 * should be kept lightweight (e.g. update a single piece of local state).
 */
export type AnnotationHoveredEvent = {
  annotationId: string | null;
  annotation: ScrollbarAnnotation | null;
};

export type ScrollbarWithAnnotationsEvents = {
  onAnnotationClicked: AnnotationClickedEvent;
  onAnnotationHovered: AnnotationHoveredEvent;
};
